def hex_word_sum(s):
    def is_valid_hex(word):
        valid_chars = set("0123456789ABCDEF")
        for char in word:
            if char not in valid_chars:
                return False
        return True

    def to_hex_value(word):
        substitutions = {'O': '0', 'S': '5'}
        hex_word = ""
        for char in word:
            if char in substitutions:
                hex_word += substitutions[char]
            else:
                hex_word += char
        return int(hex_word, 16)

    total_sum = 0
    words = s.split()

    for word in words:
        if is_valid_hex(word):
            total_sum += to_hex_value(word)

    return total_sum
